function refreshAppSourceRefs(graphId, refs) {
    const graph = graphs.find(item => item.id === graphId);
    graph.source = graph.source.split('; ').filter(reference => !reference.startsWith('app.js:')).join('; ');
    if (refs) graph.source += `${graph.source ? '; ' : ''}${refs}`;
}

